static void printMemReference(MCInst *MI, unsigned Op, SStream *O);
static void printOperand(MCInst *MI, unsigned OpNo, SStream *O);


static void set_mem_access(MCInst *MI, bool status)
{
        if (MI->csh->detail != CS_OPT_ON)
                return;

        MI->csh->doing_mem = status;
        if (!status)
                // done, create the next operand slot
                MI->flat_insn->detail->x86.op_count++;

}

static void printopaquemem(MCInst *MI, unsigned OpNo, SStream *O)
{
        // FIXME: do this with autogen
        // printf(">>> ID = %u\n", MI->flat_insn->id);
        switch(MI->flat_insn->id) {
                default:
                        SStream_concat0(O, "ptr ");
                        break;
                case X86_INS_SGDT:
                case X86_INS_SIDT:
                case X86_INS_LGDT:
                case X86_INS_LIDT:
                case X86_INS_FXRSTOR:
                case X86_INS_FXSAVE:
                case X86_INS_LJMP:
                case X86_INS_LCALL:
                        // do not print "ptr"
                        break;
        }

        switch(MI->csh->mode) {
                case CS_MODE_16:
                        switch(MI->flat_insn->id) {
                                default:
                                        MI->x86opsize = 2;
                                        break;
                                case X86_INS_LJMP:
                                case X86_INS_LCALL:
                                        MI->x86opsize = 4;
                                        break;
                                case X86_INS_SGDT:
                                case X86_INS_SIDT:
                                case X86_INS_LGDT:
                                case X86_INS_LIDT:
                                        MI->x86opsize = 6;
                                        break;
                        }
                        break;
                case CS_MODE_32:
                        switch(MI->flat_insn->id) {
                                default:
                                        MI->x86opsize = 4;
                                        break;
                                case X86_INS_LJMP:
                                case X86_INS_LCALL:
                                case X86_INS_SGDT:
                                case X86_INS_SIDT:
                                case X86_INS_LGDT:
                                case X86_INS_LIDT:
                                        MI->x86opsize = 6;
                                        break;
                        }
                        break;
                case CS_MODE_64:
                        switch(MI->flat_insn->id) {
                                default:
                                        MI->x86opsize = 8;
                                        break;
                                case X86_INS_LJMP:
                                case X86_INS_LCALL:
                                case X86_INS_SGDT:
                                case X86_INS_SIDT:
                                case X86_INS_LGDT:
                                case X86_INS_LIDT:
                                        MI->x86opsize = 10;
                                        break;
                        }
                        break;
                default:        // never reach
                        break;
        }

        printMemReference(MI, OpNo, O);
}

static void printi8mem(MCInst *MI, unsigned OpNo, SStream *O)
{
        SStream_concat0(O, "byte ptr ");
        MI->x86opsize = 1;
        printMemReference(MI, OpNo, O);
}

